def process_order(order, inventory, payment_gateway, notifier):
    if order.status == 'pending':
        if order.total > 1000:
            if payment_gateway.verify(order.payment):
                for item in order.items:
                    if inventory.check(item.sku):
                        if item.quantity <= inventory.stock(item.sku):
                            inventory.deduct(item.sku, item.quantity)
                        else:
                            notifier.send('out_of_stock', item)
                    else:
                        notifier.send('sku_not_found', item)
            else:
                return {'error': 'payment_failed'}
        else:
            for item in order.items:
                inventory.deduct(item.sku, item.quantity)
        order.status = 'confirmed'
    return order
```

